import itertools

def solve_small(n):
    # Possible pillars
    pillars = []
    # z-direction
    for x in range(n):
        for y in range(n):
            pillars.append([(x, y, z) for z in range(n)])
    # x-direction
    for y in range(n):
        for z in range(n):
            pillars.append([(x, y, z) for x in range(n)])
    # y-direction
    for x in range(n):
        for z in range(n):
            pillars.append([(x, y, z) for y in range(n)])

    return pillars

def share_vertex(p1, p2):
    # p1 and p2 are lists of cubes
    for c1 in p1:
        for c2 in p2:
            if max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2])) <= 1:
                return True
    return False

