import itertools

def solve_small_test(n):
    pillars = []
    # z-direction
    for x in range(n):
        for y in range(n):
            pillars.append(tuple([(x, y, z) for z in range(n)]))
    # x-direction
    for y in range(n):
        for z in range(n):
            pillars.append(tuple([(x, y, z) for x in range(n)]))
    # y-direction
    for x in range(n):
        for z in range(n):
            pillars.append(tuple([(x, y, z) for y in range(n)]))
    return pillars

def share_vertex(p1, p2):
    for c1 in p1:
        for c2 in p2:
            if max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2])) <= 1:
                return True
    return False

def get_hitting_set(n):
    return {(x, y, z) for x in range(n) for y in range(n) for z in range(n) if (x + y + z) % n == 0}

n = 4
pillars = solve_small_test(n)
C = get_hitting_set(n)

# To find if C is enough, we need to check if S is uniquely determined.
# But there are too many S. Let's try to find a counterexample.
# A counterexample is S1, S2 such that |S1|, |S2| >= 2, S1 != S2, and
# union_{P in S1} (P \cap C) == union_{P in S2} (P \cap C).

# Let's pick two pillars P1, P2 that share a cube c in C.
# P1 is (x, y, z) for z in range(n), P2 is (x, y, z) for x in range(n).
# They share c = (x, y, z).
# Let's pick P3 and P4 that are far away.
# S1 = {P1, P3}, S2 = {P2, P3}.
# C \cap P1 = {c}, C \cap P2 = {c}, C \cap P3 = {c3}.
# Then A1 = {c, c3} and A2 = {c, c3}.
# We just need to make sure S1 and S2 are valid.
# S1 valid means share_vertex(P1, P3) is False.
# S2 valid means share_vertex(P2, P3) is False.
# If we can find such P1, P2, P3, then C is not enough.

def find_counterexample(n):
    pillars = solve_small_test(n)
    C = get_hitting_set(n)
    for i in range(len(pillars)):
        for j in range(i + 1, len(pillars)):
            # Check if P_i and P_j share a cube in C
            common = set(pillars[i]) & set(pillars[j]) & C
            if common:
                # Found P1, P2. Now look for P3.
                for k in range(len(pillars)):
                    if k == i or k == j: continue
                    if not share_vertex(pillars[i], pillars[k]) and not share_vertex(pillars[j], pillars[k]):
                        # S1 = {P_i, P_k}, S2 = {P_j, P_k}
                        # Check if P_i and P_j share the same cube in C.
                        # Actually, any common cube in C will do.
                        # But we need union_{P in S1} (P \cap C) == union_{P in S2} (P \cap C).
                        # P_i \cap C = {c_i}, P_j \cap C = {c_j}, P_k \cap C = {c_k}.
                        # We need {c_i, c_k} == {c_j, c_k}, so c_i == c_j.
                        if set(pillars[i]) & C == set(pillars[j]) & C:
                            return (i, j, k)
    return None

print(find_counterexample(4))
